static const int kCjkGlyphCount = 5195;

inline const CjkGlyph* cjkGlyph(uint32_t cp) {
	int lo = 0, hi = kCjkGlyphCount - 1;
	while (lo <= hi) {
		int mid = (lo + hi) >> 1;
		uint32_t v = kCjkGlyphs[mid].cp;
		if (v == cp) return &kCjkGlyphs[mid];
		if (v < cp) lo = mid + 1; else hi = mid - 1;
	}
	return 0;
}
inline uint32_t utf8Next(const char*& p) {
	const unsigned char c = (unsigned char)*p;
	if (c < 0x80) { ++p; return c; }
	if ((c >> 5) == 0x6) { uint32_t cp=((c&0x1f)<<6)|(p[1]&0x3f); p+=2; return cp; }
	if ((c >> 4) == 0xe) { uint32_t cp=((c&0x0f)<<12)|((p[1]&0x3f)<<6)|(p[2]&0x3f); p+=3; return cp; }
	if ((c >> 3) == 0x1e){ uint32_t cp=((c&0x07)<<18)|((p[1]&0x3f)<<12)|((p[2]&0x3f)<<6)|(p[3]&0x3f); p+=4; return cp; }
	++p; return c;
}
